tool_input.command:
$h=@{'User-Agent'='dsh-agent'}
Write-Output '=== npm: @fish-under-sea/dsh-fish ==='
npm view '@fish-under-sea/dsh-fish' version description 2>&1 | Select-Object -First 4
Write-Output ''
Write-Output '=== fork repo docs/ ==='
try { (Invoke-RestMethod 'https://api.github.com/repos/Fish-under-sea/dsh-our-free-model-fish/contents/docs' -Headers $h -TimeoutSec 25) | Select-Object name,type | Format-Table -AutoSize | Out-String -Width 120 } catch { Write-Output "FAILED: $($_.Exception.Message)" }
Write-Output '=== fork repo catalog/ ==='
try { (Invoke-RestMethod 'https://api.github.com/repos/Fish-under-sea/dsh-our-free-model-fish/contents/catalog' -Headers $h -TimeoutSec 25) | Select-Object name,type | Format-Table -AutoSize | Out-String -Width 120 } catch { Write-Output "FAILED: $($_.Exception.Message)" }

$h=@{'User-Agent'='dsh-agent'}
$t=(Invoke-WebRequest 'https://raw.githubusercontent.com/Fish-under-sea/dsh-fish/main/README.md' -Headers $h -TimeoutSec 25 -UseBasicParsing).Content
$lines = $t -split "`n"
Write-Output "total lines: $($lines.Count)"
for ($i=0; $i -lt $lines.Count; $i++) { if ($lines[$i] -match 'our-free-model') { Write-Output ("{0}: {1}" -f ($i+1), $lines[$i].Trim()); if ($i -lt $lines.Count-1) { Write-Output ("     >> {0}" -f $lines[$i+1].Trim()) } } }
